use Illuminate\Support\Facades\Cache;

public function index()
{
    $sales = Cache::remember('dashboard.sales', now()->addMinutes(10), function () {
        return Order::query()
            ->where('status', 'paid')
            ->selectRaw('DATE(paid_at) as day, SUM(total) as amount')
            ->groupBy('day')
            ->orderBy('day')
            ->get();
    });

    return view('dashboard', ['sales' => $sales]);
}

use Illuminate\Support\Facades\Cache;

protected static function booted(): void
{
    static::saved(fn () => Cache::forget('dashboard.sales'));
    static::deleted(fn () => Cache::forget('dashboard.sales'));
}
